/* Cross-check: mirrors CalculateCommunityFlowIdv4/v6 from src/output-json.c
 * using the same packed structs and htons/ntohl logic, hashing with OpenSSL. */
#include <arpa/inet.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char b64[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void b64enc(const unsigned char *in, size_t len, char *out)
{
    size_t i = 0, o = 0;
    while (i + 3 <= len) {
        unsigned v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = b64[(v >> 6) & 63];
        out[o++] = b64[v & 63];
        i += 3;
    }
    if (len - i == 1) {
        unsigned v = in[i] << 16;
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = '=';
        out[o++] = '=';
    } else if (len - i == 2) {
        unsigned v = (in[i] << 16) | (in[i + 1] << 8);
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = b64[(v >> 6) & 63];
        out[o++] = '=';
    }
    out[o] = '\0';
}

int main(int argc, char **argv)
{
    /* argv: seed src dst proto sp dp */
    if (argc != 7) return 2;
    uint16_t seed = (uint16_t)atoi(argv[1]);
    uint8_t proto = (uint8_t)atoi(argv[4]);
    uint16_t sp_in = (uint16_t)atoi(argv[5]);
    uint16_t dp_in = (uint16_t)atoi(argv[6]);
    int v6 = strchr(argv[2], ':') != NULL;

    unsigned char hash[20];
    char out[128];

    if (!v6) {
        struct {
            uint16_t seed;
            uint32_t src;
            uint32_t dst;
            uint8_t proto;
            uint8_t pad0;
            uint16_t sp;
            uint16_t dp;
        } __attribute__((__packed__)) ipv4;

        struct in_addr a, b;
        if (inet_pton(AF_INET, argv[2], &a) != 1) return 3;
        if (inet_pton(AF_INET, argv[3], &b) != 1) return 3;
        uint32_t src = a.s_addr, dst = b.s_addr;
        uint16_t sp = sp_in, dp = dp_in;
        if (proto == 1) { /* IPPROTO_ICMP: flow stores type in a uint8_t */
            sp = (uint8_t)sp_in;
            dp = (uint8_t)dp_in;
        }
        sp = htons(sp);
        dp = htons(dp);
        ipv4.seed = htons(seed);
        if (ntohl(src) < ntohl(dst) || (src == dst && ntohs(sp) < ntohs(dp))) {
            ipv4.src = src; ipv4.dst = dst; ipv4.sp = sp; ipv4.dp = dp;
        } else {
            ipv4.src = dst; ipv4.dst = src; ipv4.sp = dp; ipv4.dp = sp;
        }
        ipv4.proto = proto;
        ipv4.pad0 = 0;
        SHA1((const unsigned char *)&ipv4, sizeof(ipv4), hash);
    } else {
        struct {
            uint16_t seed;
            uint32_t src[4];
            uint32_t dst[4];
            uint8_t proto;
            uint8_t pad0;
            uint16_t sp;
            uint16_t dp;
        } __attribute__((__packed__)) ipv6;

        unsigned char a[16], b[16];
        if (inet_pton(AF_INET6, argv[2], a) != 1) return 3;
        if (inet_pton(AF_INET6, argv[3], b) != 1) return 3;
        uint16_t sp = sp_in, dp = dp_in;
        if (proto == 58) { /* IPPROTO_ICMPV6 */
            sp = (uint8_t)sp_in;
            dp = (uint8_t)dp_in;
        }
        sp = htons(sp);
        dp = htons(dp);
        ipv6.seed = htons(seed);
