static void b64enc(const unsigned char *in, size_t len, char *out)
{
    size_t i = 0, o = 0;
    while (i + 3 <= len) {
        unsigned v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
